<script lang="ts">
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let lot=$state(''),parameter=$state('temperature');
 let series=$derived.by(()=>{const replaced=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));return model.analyses.filter(a=>a.lot_id===lot&&a.parameter===parameter&&a.quality==='measured'&&!replaced.has(a.id)).sort((a,b)=>Date.parse(a.measured_at)-Date.parse(b.measured_at));});
 let comparable=$derived(series.every(a=>a.unit===series[0]?.unit&&a.method===series[0]?.method));
 let points=$derived.by(()=>{if(!series.length||!comparable)return '';const max=Math.max(...series.map(a=>Number(a.value))),min=Math.min(...series.map(a=>Number(a.value))),start=Date.parse(series[0].measured_at),end=Date.parse(series[series.length-1].measured_at);return series.map(a=>`${40+(Date.parse(a.measured_at)-start)/(end-start||1)*520},${210-(Number(a.value)-min)/(max-min||1)*170}`).join(' ');});
</script>
<section class="card"><h2>{t('measurementSeries')}</h2><div class="selectors"><label>{t('lot_id')}<select bind:value={lot}><option value="">—</option>{#each model.lots as l}<option value={l.id}>{l.code} · {l.name}</option>{/each}</select></label><label>{t('parameter')}<select bind:value={parameter}>{#each ['temperature','sugar','alcohol','acidity','ph','free_so2'] as p}<option value={p}>{p==='ph'?'pH':t(p)}</option>{/each}</select></label></div>{#if series.length&&comparable}<svg viewBox="0 0 600 240" role="img" aria-label={t('measurementSeries')}><line x1="40" y1="210" x2="560" y2="210" stroke="#bbc8b8"/><polyline {points} fill="none" stroke="#285741" stroke-width="3" />{#each points.split(' ') as point,i}<circle cx={Number(point.split(',')[0])} cy={Number(point.split(',')[1])} r="4" fill="#285741"><title>{series[i].measured_at}: {series[i].value} {series[i].unit}</title></circle>{/each}<text x="40" y="230" font-size="10">{series[0].measured_at.slice(0,10)}</text><text x="460" y="230" font-size="10">{series[series.length-1].measured_at.slice(0,10)}</text></svg><p>{series[0].unit} · {series[0].method}</p><details><summary>{t('measurements')}</summary>{#each series as a}<p>{a.measured_at} · {a.value} {a.unit}</p>{/each}</details>{:else}<p class="muted">{series.length?t('incompatible'):t('empty')}</p>{/if}</section>
<style>.selectors{display:grid;grid-template-columns:1fr 1fr;gap:14px}svg{width:100%;margin-top:20px}@media(max-width:500px){.selectors{grid-template-columns:1fr}}</style>
